import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import {
  BUNDLED_SAMPLE_MARK,
  collectBundledSamples,
} from "../src/importer/bundled-samples.js";

/**
 * kit が同梱している既定に、**嘘の表示を出さない**（B-61）。
 *
 * 🔴 **同梱の 7 本は「前の案件の生成物」ではない。kit が手で育てている既定である。**
 * 生成されたと書いてある 2026-08-08〜09 以降、**7 本に合計 38 コミットの手直し**が
 * 入っている（`layouts/imported.blade.php` には kit 自身の設計メモまで書いてある）。
 *
 * **なのに全 7 本の先頭には、こう書いてあった:**
 *
 * ```
 * generated by agentcms template apply — 手動編集すると再 apply 時に conflict になります
 * ```
 *
 * ▷ **利用者は、触っていいものを触らない。**「自動生成だから触るな」と読めば、
 *   直したいところがあっても諦めるか、こちらへ連絡してくる。
 *   **v1.0 の目的（運用者が自分で直せる）に真っ向から反する。**
 *
 * ▷ **しかも conflict にならない。**B-60 の手当てで、触っていない見本は
 *   初回 apply が飲むようになっている。**書いてあることが起きない。**
 */
const TEMPLATE = join(import.meta.dirname, "..", "..", "..", "template");

/** 同梱の既定 7 本（1 本ずつ外して数えた結果、どれも土台だった） */
const BUNDLED = [
  "resources/views/public/home.blade.php",
  "resources/views/public/about.blade.php",
  "resources/views/public/service.blade.php",
  "resources/views/layouts/imported.blade.php",
  "resources/views/components/imported/cta.blade.php",
  "modules/Contact/views/form.blade.php",
  "modules/Works/views/index.blade.php",
];

const head = (rel: string): string =>
  readFileSync(join(TEMPLATE, rel), "utf-8").slice(0, 400);

describe("同梱の既定に嘘の表示を出さない（B-61）", () => {
  it.each(BUNDLED)("%s は「自動生成」と名乗らない", (rel) => {
    expect(head(rel)).not.toContain("generated by agentcms template apply");
  });

  it.each(BUNDLED)("%s は「手で直すな」と言わない", (rel) => {
    expect(head(rel)).not.toContain("手動編集すると");
  });

  it.each(BUNDLED)("%s は同梱の見本だと名乗る", (rel) => {
    // 名乗らないと B-60 の手当てが効かず、初回 apply が conflict に戻る
    expect(head(rel)).toContain(BUNDLED_SAMPLE_MARK);
  });

  it("🔴 名乗りを替えても、同梱の見本として数えられ続ける", () => {
    /*
     * **ここが落ちると B-60 が戻る。**
     * `collectBundledSamples()` は目印で見本を見分けているので、
     * **表示を直した瞬間に 0 件になる**という壊れ方をする。
     */
    const found = collectBundledSamples(TEMPLATE).map((s) => s.target);

    for (const rel of BUNDLED) {
      expect(found).toContain(rel);
    }
  });

  it("素の view は見本として数えない", () => {
    // 素直でない例: 目印を持たないものまで飲むと、利用者のファイルが消える
    const found = collectBundledSamples(TEMPLATE).map((s) => s.target);

    expect(found).not.toContain("resources/views/layouts/public.blade.php");
    expect(found).not.toContain("resources/views/app.blade.php");
  });
});
